(function(){
  const css='qa.css';
  if(!document.querySelector('link[data-qa-style]')){const l=document.createElement('link');l.rel='stylesheet';l.href=css;l.dataset.qaStyle='';document.head.appendChild(l)}
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function init(){const main=document.querySelector('main.workspace');if(!main||main.querySelector('.qa-panel'))return;const key='chemistry-qa-'+location.hostname;let items=[];try{items=JSON.parse(localStorage.getItem(key)||'[]')}catch{};const panel=document.createElement('section');panel.className='qa-panel';panel.innerHTML='<h2>课堂问答</h2><p class="qa-hint">把课上疑问先记下来；答案可留空，之后再补入整理后的解释。记录保存在此浏览器中。</p><form class="qa-form"><label for="qa-q">我的问题</label><textarea id="qa-q" required placeholder="例如：亲核性为什么不等于 Lewis 碱性？"></textarea><label for="qa-a">整理后的回答（可选）</label><textarea id="qa-a" placeholder="可先留空，待复习时补充。"></textarea><button>保存问答</button></form><div class="qa-list"></div>';main.appendChild(panel);const list=panel.querySelector('.qa-list');const render=()=>{list.innerHTML=items.length?items.map((x,i)=>'<article class="qa-item"><h3>'+esc(x.q)+'</h3><p>'+esc(x.a||'待补充回答')+'</p><div class="qa-meta"><span>'+esc(x.date)+'</span><button class="qa-delete" type="button" data-i="'+i+'">删除</button></div></article>').join(''):'<p class="qa-hint">还没有记录。</p>';};panel.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const q=panel.querySelector('#qa-q').value.trim();if(!q)return;items.unshift({q,a:panel.querySelector('#qa-a').value.trim(),date:new Date().toLocaleString('zh-CN')});localStorage.setItem(key,JSON.stringify(items));e.target.reset();render()});list.addEventListener('click',e=>{const b=e.target.closest('[data-i]');if(!b)return;items.splice(Number(b.dataset.i),1);localStorage.setItem(key,JSON.stringify(items));render()});render()}
  async function enhanceTerm(){if(!location.pathname.endsWith('term.html'))return;const slug=new URLSearchParams(location.search).get('slug');if(!slug)return;try{const terms=await (await fetch('data/terms.json')).json();const t=terms.find(x=>x.slug===slug);if(!t||(!t.formula&&!t.derivation&&!t.notation))return;const detail=document.querySelector('#term-detail');if(!detail)return;const add=()=>{if(detail.querySelector('.term-formula'))return;const sec=document.createElement('section');sec.className='term-formula';sec.innerHTML='<h2>公式与符号</h2>'+(t.formula?'<div class="formula">'+t.formula+'</div>':'')+(t.derivation?'<p><b>推导思路：</b>'+t.derivation+'</p>':'')+(t.notation?'<p><b>符号说明：</b>'+t.notation+'</p>':'');detail.appendChild(sec)};if(detail.children.length)add();else new MutationObserver(add).observe(detail,{childList:true});}catch{}}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
  enhanceTerm();
})();
